"""The tools the agents use: one HTTP endpoint of a system of record each (generated by G2C as
stubs; completed by hand). config["tools"] = tools().

execute() (inherited from E2A's BaseToolService, public) validates the input, applies the commit
gate and runs the call through the tool's resilience policy. Agents reach a tool only through
io_read (reads, retried freely) or io_modify (material: always with an idempotency key; a
transport failure is UNKNOWN, never a blind retry), limited by the governance tool_policy. Every
result carries physical_success and a typed outcome: a model's text is never the truth.

The tenant comes from the request context, never from the model. Calls carry this service's own
identity when a credential provider is bound (E2A v1.11.0: on Cloud Run, the service account's
Google ID token, E2A_WORKLOAD_IDENTITY=gcp_id_token); each system of record checks it, and the
tenant and the action, itself.

The four systems (their base URLs from the environment):
  RECONCILIATION_API_URL  reconciliation-service  open exceptions and bank lines (the service routes)
  SETTLEMENT_API_URL      settlement-service      settlements, events, adjustments (the ledger)
  O2C_API_URL             o2c-agent-service       orders
  AUDIT_API_URL           audit-ai-service        audit findings per settlement
"""
import os
from typing import Any, Callable, Dict, Optional

import httpx
from e2a import PhysicalOutcome, RestToolService

URL_DEFAULTS = {"RECONCILIATION_API_URL": "http://localhost:8001", "SETTLEMENT_API_URL": "http://localhost:8080",
                "O2C_API_URL": "http://localhost:8002", "AUDIT_API_URL": "http://localhost:8003"}


class HttpJsonTool(RestToolService):
    """One HTTP endpoint of a system of record."""

    def __init__(self, name: str, base_url: str, method: str, path: str, required: tuple = (),
                 success: Callable[[int, Any], bool] = None, definitive: Callable[[int, Any], bool] = None,
                 transport: Optional[httpx.AsyncBaseTransport] = None, material: bool = False) -> None:
        self.name, self.base_url, self.method, self.path = name, base_url.rstrip("/"), method, path
        self.required, self.material = required, material
        self.success = success or (lambda status, body: 200 <= status < 300)
        self.definitive = definitive or (lambda status, body: 400 <= status < 500)
        self.transport = transport

    def _get_endpoint(self, config=None, tenant_id=None, **kwargs):
        return self.base_url + self.path

    def _validate_input(self, payload, config=None, **kwargs):
        """Arguments are checked here, at execution, not by the prompt: every required field present
        and no path argument that could change the route."""
        for field in self.required:
            value = payload.get(field)
            if value in (None, ""):
                return False
            if field != "json" and (any(c in str(value) for c in "/?#%\\") or len(str(value)) > 100):
                return False
        return True

    def _build_payload(self, payload, config=None, **kwargs):
        return payload

    def _headers(self, kwargs) -> Dict[str, str]:
        headers = {"X-Tenant-Id": kwargs["tenant_id"], **(kwargs.get("auth_headers") or {})}
        if kwargs.get("idempotency_key"):
            headers["Idempotency-Key"] = kwargs["idempotency_key"]
        if kwargs.get("correlation_id"):
            headers["X-Correlation-Id"] = kwargs["correlation_id"]
        return headers

    async def _send_request(self, endpoint, body, token=None, timeout=None, config=None, **kwargs):
        body = dict(body)
        url = endpoint.format(**body)
        params, json_body = body.pop("params", None), body.pop("json", None)
        async with httpx.AsyncClient(transport=self.transport, timeout=timeout) as client:
            response = await client.request(self.method, url, params=params, json=json_body,
                                            headers=self._headers(kwargs))
            data = response.json() if response.content else None
            if response.status_code >= 500:
                # not definitive: raise so the resilience policy may retry a replay-safe call
                raise RuntimeError(f"{self.name}: HTTP {response.status_code}")
            result = self._result(response.status_code, data)
            return await self._after(client, result, body, kwargs)

    def _result(self, status: int, data: Any) -> Dict[str, Any]:
        ok = self.success(status, data)
        outcome = (PhysicalOutcome.COMMITTED if ok else
                   PhysicalOutcome.NOT_COMMITTED if self.definitive(status, data) else PhysicalOutcome.UNKNOWN)
        return {"status": status, "physical_success": ok, "outcome": outcome, "body": data}

    async def _after(self, client, result, body, kwargs) -> Dict[str, Any]:
        return result


class PostAdjustment(HttpJsonTool):
    """The one material tool: a write-off or refund in settlement-service's ledger, then a read-back.

    settlement-service de-duplicates on the Idempotency-Key, so a retry or a replayed approval
    returns the first result and never posts twice. After a 201 the adjustment is read back from
    the ledger (GET .../adjustments): the receipt says whether the ledger shows it."""

    def __init__(self, base_url: str, transport=None) -> None:
        super().__init__("post_adjustment", base_url, "POST", "/api/v1/settlements/{settlement_id}/adjustments",
                         required=("settlement_id", "json"), success=lambda status, body: status in (200, 201),
                         # 409 while the same key is still in progress there is not definitive: UNKNOWN
                         definitive=lambda status, body: status in (200, 201, 400, 404, 422),
                         transport=transport, material=True)

    async def _after(self, client, result, body, kwargs):
        if not result["physical_success"]:
            return result
        adjustment_id = (result["body"] or {}).get("adjustmentId")
        url = self.base_url + f"/api/v1/settlements/{body['settlement_id']}/adjustments"
        try:
            listed = await client.get(url, headers=self._headers({**kwargs, "idempotency_key": None}))
            rows = listed.json() if listed.status_code == 200 and listed.content else []
            result["read_back"] = any(str(r.get("adjustmentId")) == str(adjustment_id) for r in (rows or []))
        except httpx.HTTPError:
            result["read_back"] = False             # posted (201); the read-back is retried by the caller
        return result


def tools(env: Dict[str, str] = None, transports: Dict[str, Any] = None) -> Dict[str, HttpJsonTool]:
    """The service's tools. `transports` (tests, the landscape stand-ins) maps a base-URL variable
    to an httpx transport."""
    env = os.environ if env is None else env
    transports = transports or {}
    url = lambda key: env.get(key) or URL_DEFAULTS[key]
    t = lambda key: transports.get(key)
    recon, settlement = "RECONCILIATION_API_URL", "SETTLEMENT_API_URL"
    o2c, audit = "O2C_API_URL", "AUDIT_API_URL"
    return {
        # reconciliation-service's service route (reconciliation.read): the exceptions, filtered by line
        "get_reconciliation_exception": HttpJsonTool(
            "get_reconciliation_exception", url(recon), "GET", "/service/v1/exceptions", transport=t(recon)),
        # one bank line (what was paid): reconciliation-service's service route, reconciliation.read
        "get_bank_line": HttpJsonTool(
            "get_bank_line", url(recon), "GET", "/service/v1/lines/{line_id}", required=("line_id",),
            transport=t(recon)),
        "get_settlement": HttpJsonTool(
            "get_settlement", url(settlement), "GET", "/api/v1/settlements/{settlement_id}",
            required=("settlement_id",), transport=t(settlement)),
        "get_settlement_events": HttpJsonTool(
            "get_settlement_events", url(settlement), "GET", "/api/v1/events", transport=t(settlement)),
        "get_order": HttpJsonTool(
            "get_order", url(o2c), "GET", "/api/v1/orders/{order_id}", required=("order_id",), transport=t(o2c)),
        "get_audit_findings": HttpJsonTool(
            "get_audit_findings", url(audit), "GET", "/audits/{settlement_id}", required=("settlement_id",),
            transport=t(audit)),
        # reconciliation-service's service route (reconciliation.resolve): closes the exception once the
        # ledger shows the adjustment (reconciliation reads the ledger; it does not believe this call)
        "resolve_exception": HttpJsonTool(
            "resolve_exception", url(recon), "POST", "/service/v1/exceptions/{line_id}/resolve",
            required=("line_id", "json"), success=lambda status, body: status == 200,
            definitive=lambda status, body: status in (200, 404, 422), transport=t(recon), material=True),
        "post_adjustment": PostAdjustment(url(settlement), transport=t(settlement)),
    }
